CREATE TABLE "all_types_table" ("id" VARCHAR2(20) NOT NULL, "varchar2_col" VARCHAR2(4000), "varchar_col" VARCHAR(4000), "char_col" CHAR(2000), "character_col" CHARACTER(2000), "nvarchar2_col" NVARCHAR2(2000), "nchar_col" NCHAR(1000), "nchar_varying_col" NCHAR VARYING(2000), "nat_character_col" NATIONAL CHARACTER(1000), "nat_char_col" NATIONAL CHAR(1000), "nat_characvar_col" NATIONAL CHARACTER VARYING(2000), "nat_charvar_col" NATIONAL CHAR VARYING(2000), "number_col" NUMBER, "numeric_col" NUMERIC, "decimal_col" DECIMAL, "dec_col" DEC, "float_col" FLOAT, "double_prec_col" DOUBLE PRECISION, "real_col" REAL, "integer_col" INTEGER, "int_col" INT, "smallint_col" SMALLINT, "binary_float_col" BINARY_FLOAT, "binary_double_col" BINARY_DOUBLE, "date_col" DATE, "timestamp_col" TIMESTAMP(6), "timestamp_tz_col" TIMESTAMP(6) WITH TIME ZONE, "timestamp_ltz_col" TIMESTAMP(6) WITH LOCAL TIME ZONE, "raw_col" RAW(2000), "blob_col" BLOB, "clob_col" CLOB, "nclob_col" NCLOB, PRIMARY KEY ("id"));
CREATE TABLE "pk_strings_table" ("varchar2_pk" VARCHAR2(100) NOT NULL, "varchar_pk" VARCHAR(100) NOT NULL, "char_pk" CHAR(10) NOT NULL, "character_pk" CHARACTER(10) NOT NULL, "nvarchar2_pk" NVARCHAR2(100) NOT NULL, "nchar_pk" NCHAR(10) NOT NULL, "nchar_varying_pk" NCHAR VARYING(100) NOT NULL, "nat_character_pk" NATIONAL CHARACTER(10) NOT NULL, "nat_char_pk" NATIONAL CHAR(10) NOT NULL, "nat_characvar_pk" NATIONAL CHARACTER VARYING(100) NOT NULL, "nat_charvar_pk" NATIONAL CHAR VARYING(100) NOT NULL, "raw_pk" RAW(16) NOT NULL, "val_col" VARCHAR2(20), PRIMARY KEY ("varchar2_pk", "varchar_pk", "char_pk", "character_pk", "nvarchar2_pk", "nchar_pk", "nchar_varying_pk", "nat_character_pk", "nat_char_pk", "nat_characvar_pk", "nat_charvar_pk", "raw_pk"));
CREATE TABLE "pk_numbers_table" ("number_pk" NUMBER NOT NULL, "numeric_pk" NUMERIC NOT NULL, "decimal_pk" DECIMAL NOT NULL, "dec_pk" DEC NOT NULL, "float_pk" FLOAT NOT NULL, "double_prec_pk" DOUBLE PRECISION NOT NULL, "real_pk" REAL NOT NULL, "binary_float_pk" BINARY_FLOAT NOT NULL, "binary_double_pk" BINARY_DOUBLE NOT NULL, "integer_pk" INTEGER NOT NULL, "int_pk" INT NOT NULL, "smallint_pk" SMALLINT NOT NULL, "date_pk" DATE NOT NULL, "timestamp_pk" TIMESTAMP(6) NOT NULL, "timestamp_ltz_pk" TIMESTAMP(6) WITH LOCAL TIME ZONE NOT NULL, "val_col" VARCHAR2(20), PRIMARY KEY ("number_pk", "numeric_pk", "decimal_pk", "dec_pk", "float_pk", "double_prec_pk", "real_pk", "binary_float_pk", "binary_double_pk", "integer_pk", "int_pk", "smallint_pk", "date_pk", "timestamp_pk", "timestamp_ltz_pk"));
